import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BsgK4TUM.js";const c=JSON.parse('{"title":"Initial Setup","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/configuration.md","filePath":"user-guide/configuration.md"}'),i={name:"user-guide/configuration.md"};function n(r,e,d,p,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="initial-setup" tabindex="-1">Initial Setup <a class="header-anchor" href="#initial-setup" aria-label="Permalink to &quot;Initial Setup&quot;">​</a></h1><p>After installing you should review some commonly changed settings before populating your store with products.</p><p>As an Administrator visit, <strong>Store / Settings</strong> within Concrete CMS&#39;s Dashboard.</p><p>A suggested checklist of items to review is as follows:</p><ul><li><strong>Currency</strong> - Adjust the currency for the store</li><li><strong>Tax</strong> - Adjust whether entered product prices are inclusive or exclusive of taxes</li><li><strong>Shipping</strong> - Adjust the units for weight and size</li><li><strong>Notifications and Receipts</strong> - Enter one or more emails for order notifications to be sent to</li><li><strong>Cart and Checkout</strong> - Adjust the guest checkout setting</li></ul><h2 id="tax-setup" tabindex="-1">Tax Setup <a class="header-anchor" href="#tax-setup" aria-label="Permalink to &quot;Tax Setup&quot;">​</a></h2><p>There are two ways that prices can be entered into Community Store, inclusive and exclusive of taxes. This setting is adjusted via the Tax section of <strong>Store / Settings</strong> within the dashboard - ensure you configure this setting before entering products.</p><p>There are two steps to configure taxes:</p><ul><li>First, add a new tax rate via <strong>Store / Settings / Tax</strong> and the &#39;Add Tax Rate&#39; button</li><li>Second, &#39;Edit a Tax Class&#39; and add the newly added Tax Rate to the list of rates</li></ul><p>By default, the add-on installs a &#39;Default&#39; tax class, and this is then automatically applied to all products. Further Tax Classes allow different taxes to be applied in groups to specific products.</p><h2 id="payment-gateways" tabindex="-1">Payment Gateways <a class="header-anchor" href="#payment-gateways" aria-label="Permalink to &quot;Payment Gateways&quot;">​</a></h2><p>By default Community Store installs only one Payment Method, <strong>Invoice</strong>. This method is intended for situations where immediate payments are not required or for testing purposes.</p><p>Additional payment methods can be <a href="https://github.com/concretecms-community-store" target="_blank" rel="noreferrer">downloaded from github</a> as Concrete CMS add-ons.</p><p>Once installed, each payment method is enabled and configured from the Payments section of <strong>Store / Settings</strong> within the dashboard. Typically each Payment Method needs keys or other credentials entered.</p><p>More than one payment method can be enabled at a time.</p><h2 id="shipping-methods" tabindex="-1">Shipping Methods <a class="header-anchor" href="#shipping-methods" aria-label="Permalink to &quot;Shipping Methods&quot;">​</a></h2><p>There are two shipping methods installed by default:</p><ul><li><strong>Flat Rate</strong> - allows shipping to be calculated from a base rate, plus a rate based on quantity or weight</li><li><strong>Free Shipping</strong> - offers free shipping when certain price or weight thresholds are met</li></ul><p>The two shipping methods (and most others available) can be configured to only offer shipping to selected countries. Multiple shipping options of the same kind can be enabled, to create different shipping cost structures per country.</p><p>A common situation is that free shipping is offered on orders over a certain price. For example, if you offer free shipping on orders $200 and above, Add a &#39;Free Shipping&#39; shipping method and configure its &#39;Minimum Purchase Amount for this rate to apply&#39; value to 200. Then, on your paid shipping method(s), set the &#39;Maximum Purchase Amount for this rate to apply&#39; to 199.99</p><p>Like Payment Methods, additional shipping methods can be <a href="https://github.com/concretecms-community-store" target="_blank" rel="noreferrer">downloaded from github</a> as Concrete CMS add-ons.</p><p>For complex shipping calculation requirements, further custom shipping methods can be developed as add-ons. <a href="https://github.com/concretecms-community-store/community_store_shipping_example" target="_blank" rel="noreferrer">An example shipping method is available on github</a> to act as template for new methods.</p><h2 id="suspending-sales" tabindex="-1">Suspending Sales <a class="header-anchor" href="#suspending-sales" aria-label="Permalink to &quot;Suspending Sales&quot;">​</a></h2><p>Sales can be suspended, for example while a store is closed for a holiday period, or disabled entirely so that products are displayed without being able to be purchased (a &#39;catalog mode&#39;).</p><p>This is configured in the <strong>Sales Suspension</strong> section of <strong>Store / Settings</strong>, where a suspension can be given a start and end date/time, and a message to display to customers. The <strong>Suspension Message</strong> block can be placed on pages to display this message while sales are suspended.</p>',25)])])}const g=t(i,[["render",n]]);export{c as __pageData,g as default};
